import{_ as t,o as r,c as a,ah as n}from"./chunks/framework.Bja9t6Wf.js";const f=JSON.parse('{"title":"Research: The \\"Postenschacher\\" Case (August Wöginger)","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/postenschacher-woeginger.md","filePath":"en/recherche/postenschacher-woeginger.md"}'),o={name:"en/recherche/postenschacher-woeginger.md"};function i(s,e,h,l,c,u){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="research-the-postenschacher-case-august-woginger" tabindex="-1">Research: The &quot;Postenschacher&quot; Case (August Wöginger) <a class="header-anchor" href="#research-the-postenschacher-case-august-woginger" aria-label="Permalink to &quot;Research: The &quot;Postenschacher&quot; Case (August Wöginger)&quot;">​</a></h1><p><strong>The case of the parliamentary group leader: When political intervention meets abuse of office.</strong></p><p>Parallel to the historical machinations of the Horten era, the current political landscape of Austria provides ample material for our mockumentary. A prime example of modern intervention is the trial against ÖVP parliamentary group leader <strong>August Wöginger</strong>, who is currently (as of February/March 2026) standing trial at the Linz Regional Court.</p><hr><h2 id="the-allegation-incitement-to-abuse-of-office" tabindex="-1">The Allegation: Incitement to Abuse of Office <a class="header-anchor" href="#the-allegation-incitement-to-abuse-of-office" aria-label="Permalink to &quot;The Allegation: Incitement to Abuse of Office&quot;">​</a></h2><p>The Economic and Corruption Prosecutor&#39;s Office (WKStA) accuses August Wöginger of intervening with <strong>Thomas Schmid</strong> (then Secretary General in the Ministry of Finance) in 2017.</p><ul><li><strong>The Goal:</strong> An ÖVP mayor from the Schärding district was to be given the post of head of the Braunau-Ried-Schärding tax office.</li><li><strong>The Problem:</strong> Another applicant, Christa Scharf, was considered technically better qualified by the Federal Administrative Court. However, she was bypassed.</li><li><strong>Wöginger&#39;s Role:</strong> He is considered the &quot;inciter,&quot; as he allegedly encouraged the decision-makers to make the unlawful appointment.</li></ul><hr><h2 id="current-status-of-the-court-hearing-february-2026" tabindex="-1">Current Status of the Court Hearing (February 2026) <a class="header-anchor" href="#current-status-of-the-court-hearing-february-2026" aria-label="Permalink to &quot;Current Status of the Court Hearing (February 2026)&quot;">​</a></h2><p>After an originally planned diversion (payment of a fine without admission of guilt) was overturned by the Linz Higher Regional Court, the main trial is now underway.</p><h3 id="_1-testimonies-of-co-defendants-feb-26-27-2026" tabindex="-1">1. Testimonies of Co-Defendants (Feb 26/27, 2026) <a class="header-anchor" href="#_1-testimonies-of-co-defendants-feb-26-27-2026" aria-label="Permalink to &quot;1. Testimonies of Co-Defendants (Feb 26/27, 2026)&quot;">​</a></h3><p>In the last two days, the two co-accused finance officials were questioned separately:</p><ul><li><strong>The Commission Chairman (Siegfried M.):</strong> Pleads &quot;not guilty&quot; and emphasizes the correctness of the hearing.</li><li><strong>The Personnel Representative (Herbert B.):</strong> Admitted that Thomas Schmid asked him to support the mayor (&quot;that it should be the mayor&quot;), but denies manipulating the evaluation.</li></ul><h3 id="_2-the-next-step-woginger-testifies" tabindex="-1">2. The Next Step: Wöginger Testifies <a class="header-anchor" href="#_2-the-next-step-woginger-testifies" aria-label="Permalink to &quot;2. The Next Step: Wöginger Testifies&quot;">​</a></h3><ul><li><strong>March 3, 2026:</strong> August Wöginger is summoned for personal examination.</li><li><strong>Statutory Penalty:</strong> If convicted, he faces six months to five years in prison.</li><li><strong>Political Consequences:</strong> Wöginger has already announced that he will not resign as parliamentary group leader even in the event of a first-instance conviction.</li></ul><hr><h2 id="significance-for-the-horten-mystery" tabindex="-1">Significance for &quot;The Horten Mystery&quot; <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;Significance for &quot;The Horten Mystery&quot;&quot;">​</a></h2><p>In our mockumentary, we draw parallels between the historical favoring of &quot;friends&quot; (such as Helmut Horten by the Nazi regime) and modern political patronage.</p><ul><li><strong>The Motif of &quot;Intervention&quot;:</strong> It shows that power is consolidated not only through money (donations) but also through access to state structures (appointments).</li><li><strong>Satirical Implementation:</strong> We plan a scene in which a fictional politician attempts to reinterpret an intervention as &quot;regional structural development&quot; – very much in the style of Wöginger&#39;s line of defense.</li></ul><hr><p><em>Sources: Current reporting (Trend, Krone, Kurier, OE24) from February 27, 2026, files of the WKStA.</em></p>',21)])])}const d=t(o,[["render",i]]);export{f as __pageData,d as default};
